MAP
    NAME "SS_MAP_GRAL_SENTIDO_CALLES"
    INCLUDE 'includes/globals.map'
    WEB
        INCLUDE "includes/temp_directory.map"
        METADATA
            INCLUDE 'includes/common_metadata.map'
        END #METADATA
    END #WEB
	CONFIG "MS_ERRORFILE" "/srv/mapserver/err_sentido_calles.log"
    DEBUG 0
    LAYER
        NAME "SS_MAP_GRAL_SENTIDO_CALLES"
        PROJECTION
			'init=epsg:32614'
		END #PROJECTION
        STATUS DEFAULT
        CONNECTIONTYPE POSTGIS
        INCLUDE 'includes/conexion.map'
        TYPE LINE
        DATA "geometry from calles_navteq using unique gid srid=326142"
        STATUS DEFAULT
        CLASSITEM 'sentido'
        MINSCALE 1
        MAXSCALE 6000
        LABELCACHE ON
        CLASS
            NAME 'Sentido 1'
            EXPRESSION 'F'
            STYLE
                COLOR 150 150 150
                GAP -60
                SIZE 20
                SYMBOL "flechas2"
            END # STYLE
        END #CLASS
        CLASS
            NAME "Sentido 2"
            EXPRESSION 'T'
            STYLE
                COLOR 150 150 150
                GAP -60
                SIZE 19
                SYMBOL "flechas3"
            END # STYLE
        END #CLASS
        CLASS
            NAME "Doble Sentido"
            EXPRESSION 'B'
            STYLE
                COLOR 150 150 150
                GAP -60
                SIZE 19
                SYMBOL "flechas4"
            END # STYLE
        END #CLASS
    END #LAYER
END #MAP